        { 6921, "H", 21, 27, "耶努萨克雷", "灰谷 - 佐拉姆加前哨站 11,33", nil, false, nil, nil, "把深渊之核交给灰谷佐拉姆加前哨站的耶努萨克雷。", "深渊之核在副本内的水域里。拿到后阿奎尼斯男爵会出现并攻击你，他掉一件任务物品，也一并带给耶努萨克雷。深渊之核在尾王前的大水池中央水下（不用进尾王的房间）。", {{21,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {16762}, nil, 12736, "耶努萨克雷", { xp = 2750, money = 4500, rep = { {530, 150, "暗矛巨魔"} } } },
