        { 377, "A", 22, 26, "米尔斯迪普议员", "暮色森林 - 夜色镇 72,47", nil, false, nil, {2033, 2906}, "杀死迪克斯特·瓦德，把他的手带回去给夜色镇的米尔斯迪普议员作证明。", "迪克斯特·瓦德在副本内。", {{22,2}, {24,3}, {29,4}, {34,5}}, {3628}, nil, 270, "议员米尔斯迪普", { xp = 2100, rep = { {72, 100, "暴风城"} } } },
        { 378, "A", 22, 27, "莫特雷·加玛森", "湿地 - 丹莫德 49,18", "黑铁战争", false, {303}, {3562, 1264}, "把卡姆·深怒的头颅交给丹莫德的莫特雷·加玛森。", "前置任务同样找莫特雷·加玛森接。卡姆·深怒在副本内。", {{22,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {3640}, nil, 1074, "莫特雷·加玛森", { xp = 2750, rep = { {47, 150, "铁炉堡"} } } },
        { 386, "A", 22, 25, "卫兵伯尔顿", "赤脊山 - 湖畔镇 26,46", nil, false, nil, {3400, 1317}, "把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。", "塔格尔在副本内。塔格尔通常刷在中央区右手第一间或左手第二间牢房，偶尔刷在左右两翼之间最北端的牢房。", {{22,2}, {23,3}, {28,4}, {33,5}}, {3630}, nil, 859, "卫兵伯尔顿", { xp = 2000, rep = { {72, 100, "暴风城"} } } },
        { 387, "A", 22, 26, "典狱官塞尔沃特", "暴风城 - 监狱 51,69", nil, false, nil, nil, "替暴风城典狱官塞尔沃特清点监狱：杀 10 名迪菲亚囚徒、8 名迪菲亚罪犯、8 名迪菲亚叛军。", "任务由副本外的典狱官发放。", {{22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 1719, "典狱官塞尔沃特", { xp = 2650, money = 4000, rep = { {72, 150, "暴风城"} } } },
        { 388, "A", 22, 26, "尼科瓦·拉斯克", "暴风城 - 旧城区 75,63", nil, false, nil, nil, "收集 10 条红色毛纺面罩，交给暴风城的尼科瓦·拉斯克。", "尼科瓦·拉斯克在旧城区一带走动；监狱里的敌人基本都会掉面罩。", {{22,2}, {24,3}, {29,4}, {34,5}}, {2909}, nil, 1721, "尼科瓦·拉斯克", { xp = 2650, money = 4000, rep = { {72, 150, "暴风城"} } } },
