    ["city_of_dalaran"] = {
        { 92457, "A", 24, 33, "大法师莫德拉的影像", "奥特兰克山脉 - 达拉然城副本外", nil, false, nil, {279837, 279838}, "替达拉然城外的大法师莫德拉，击杀城内的觅索残迹（Seeking Remnant）×8、饱和残迹（Saturated Remnant）×8、法力回响（Mana Echo）×8。", "起始在副本外（大法师莫德拉的影像），开始并结束于同处。三种奥术元素怪都在达拉然城内：觅索残迹、饱和残迹、法力回响。精确坐标待实机核实。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 269127, "大法师莫德拉的影像", { xp = 9400, rep = { {2740, 100, "肯瑞托"} } } },
        { 92489, "A", 24, 33, "高阶巫师安多玛斯", "暴风城 - 法师区", nil, false, nil, {251962, 279849}, "替暴风城的高阶巫师安多玛斯，消灭达拉然城内的奥术谜团（Arcanic Enigma）。", "起始并结束于暴风城法师区的高阶巫师安多玛斯。奥术谜团是复苏之路上的精英怪，会沉默 10 秒并召唤奥术法力苗 —— 它与名单里「法力吞噬者/法力元素」占位的对应关系待实机确认。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5694, "高阶巫师安多玛斯", { xp = 9400 } },
        { 92432, "A", 30, 33, "使者雅克", "希尔斯布莱德丘陵 - 南海镇", "紧急求援", false, nil, nil, "向达拉然城附近的大法师莫德拉的影像汇报。", "在希尔斯布莱德丘陵南海镇的使者雅克处接取（可共享）。联盟链：紧急求援（使者雅克→莫德拉的影像）→ 动乱之源（莫德拉的影像处接取，进城收集奥术微粒，自动发放「达拉然下水道钥匙」）→ 肯瑞托之友（莫德拉的影像处接取，交付给紫罗兰城堡的大法师塞林德拉）。", {{30,1}, {31,2}, {36,3}, {42,4}}, nil, nil, 247264, "使者雅克", { xp = 660 } },
        { 92458, "A", 24, 33, "大法师莫德拉的影像", "银松森林 - 达拉然城副本外", "动乱之源", false, {92432}, {279839, 279840, 279841}, "为达拉然城外的大法师莫德拉的影像，取回城内的奥术微粒。", "接取并交付都在副本外的大法师莫德拉的影像。联盟链：紧急求援（南海镇使者雅克接取，汇报到莫德拉的影像处）→ 本任务（进城收集奥术微粒）→ 肯瑞托之友（莫德拉的影像处接取，交付给紫罗兰城堡的大法师塞林德拉）。接本任务即自动发放「达拉然下水道钥匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "大法师莫德拉的影像", { xp = 9400, rep = { {2740, 100, "肯瑞托"} } } },
        { 92459, "A", 24, 33, "大法师莫德拉的影像", "银松森林 - 达拉然城副本外", "肯瑞托之友", false, {92458}, nil, "带着奥术微粒回到达拉然城，与大法师塞林德拉谈谈。", "在大法师莫德拉的影像处接取，任务提供「奥术微粒」。进城交付给紫罗兰城堡的大法师塞林德拉；若版本更新后联盟被拦在城外，则在副本入口外交付。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 269127, "大法师莫德拉的影像", { xp = 265 } },
        { 92456, "A", 24, 33, "莎拉米尔", "暴风城 - 法师区", nil, false, nil, {279835, 279836}, "为暴风城的莎拉米尔，从达拉然城采回一朵注入邪能的花朵。", "起始并结束于暴风城法师区的莎拉米尔。注入邪能的花朵出自城内邪能植被，多半在邪能古树一带 —— 精确掉落来源待实机核实。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5502, "莎拉米尔", { xp = 9400 } },
        { 96986, "H", 24, 33, "梅里萨拉", "希尔斯布莱德丘陵 - 塔伦米尔", nil, false, nil, {251963, 251965}, "替塔伦米尔的梅里萨拉，击败达拉然城内的墓穴骑士阿特雷克西斯。", "起始并结束于塔伦米尔的梅里萨拉。阿特雷克西斯在下水道深处的仪式法阵，BlizzCon 试玩中他会缴械当前目标 —— 坦克被缴械期间注意减伤。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 2278, "梅里萨拉", { xp = 9400 } },
        { 96988, "H", 24, 33, "马丁·费尔本", "幽暗城 - 炼金区", nil, false, nil, {279847, 279848}, "为幽暗城的马丁·费尔本，从达拉然城收集 6 枚开裂的哨兵核心。", "起始并结束于幽暗城的马丁·费尔本。开裂的哨兵核心多半由城内奥术魔像/哨兵造型怪掉落 —— 精确来源待实机核实。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 11044, "马丁·费尔本", { xp = 9400 } },
        { 92434, "H", 30, 34, "大法师沃迪恩·伍德格莱尔", "希尔斯布莱德丘陵 - 塔伦米尔", "喋血街头", false, nil, nil, "沿洛丹伦湖寻找进入达拉然城的办法。", "在塔伦米尔的大法师沃迪恩·伍德格莱尔处接取（需先完成他发放的其余任务），任务提供「肮脏的钥匙」。沿洛丹伦湖岸找到达拉然城北缘的下水道入口潜入城中，交付给城外的大法师莫德拉的影像。", {{30,1}, {32,2}, {37,3}, {43,4}}, {279469}, nil, 2410, "大法师沃迪恩·伍德格莱尔", { xp = 270 } },
        { 96984, "H", 24, 33, "大法师莫德拉的影像", "银松森林 - 达拉然城副本外", "动乱之源", false, {92434}, {279842, 279843, 279844}, "为塔伦米尔的大法师沃迪恩·伍德格莱尔，取回达拉然城内的奥术微粒。", "接取在副本外的大法师莫德拉的影像处，交付回塔伦米尔的沃迪恩·伍德格莱尔。部落链：喋血街头（塔伦米尔接取，潜入达拉然，交付在莫德拉的影像处）→ 本任务（进城收集奥术微粒）→ 精明的谈判（回塔伦米尔接，交付给紫罗兰城堡的大法师塞林德拉）。接本任务即自动发放「达拉然下水道钥匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "大法师莫德拉的影像", { xp = 9400 } },
        { 97287, "H", 24, 33, "大法师沃迪恩·伍德格莱尔", "希尔斯布莱德丘陵 - 塔伦米尔", "精明的谈判", false, {96984}, nil, "带着奥术微粒回到达拉然城，与大法师塞林德拉谈谈。", "在塔伦米尔的大法师沃迪恩·伍德格莱尔处接取，任务提供「奥术微粒」。交付给紫罗兰城堡的大法师塞林德拉；若版本更新后部落被拦在城外，则在副本入口外交付（即发钥匙的莫德拉的影像处）。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 2410, "大法师沃迪恩·伍德格莱尔", { xp = 270 } },
        { 96987, "H", 24, 33, "雷克西·铜钳", "奥特兰克山脉 - 达拉然城下水道入口附近", nil, false, nil, nil, "从达拉然城取回《达拉然的建立》，交给下水道入口附近的雷克西·铜钳。", "发布者雷克西·铜钳守在下水道入口附近，确切位置待实机核实。《达拉然的建立》是队伍中每人都能拾取的任务物品 —— 一队人可各自完成。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, nil, "雷克西·铜钳", { xp = 9400 } },
    },
    ["gnomeregan"] = {
        { 2843, "H", 20, 35, "斯库提", "荆棘谷 - 藏宝海湾 27,77", "主工程师斯库提", false, {2842}, {9173}, "等斯库提把地精传送器调好。", "前置可从索维克(奥格瑞玛-荣誉谷 75,25)接。完成后就能使用藏宝海湾的传送器。◎ 哥布林转发器用完可以丢掉，丢了再找斯库提说一声就能再领一个。", {{20,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7853, "斯库提", nil },
        { 2922, "A", 20, 26, "工匠大师欧沃斯巴克", "铁炉堡 - 侏儒区 69,50", "工匠大师欧沃斯巴克", false, {2923}, nil, "把尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。", "前置可从萨尔努修士接(暴风城-教堂广场 51,48)。尖端机器人在进副本前、后门附近。", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {9277}, nil, 7944, "工匠大师欧沃斯巴克", { xp = 2650, money = 2000, rep = { {54, 150, "诺莫瑞根流亡者"} } } },
        { 2926, "A", 20, 27, "奥齐·电环", "丹莫罗 - 卡拉诺斯 45,49", "灾难之后", false, {2927}, nil, "用空铅瓶从辐射入侵者或辐射抢劫者身上收集放射尘，装满后交给卡拉诺斯的奥齐·电环。", "前置可从诺恩接(铁炉堡-侏儒区 69,50)。取样方法：对活着的辐射入侵者/抢劫者使用空铅瓶。", {{20,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {9284, 9283}, nil, 1268, "奥齐·电环", { xp = 2200, money = 2200, rep = { {54, 100, "诺莫瑞根流亡者"} } } },
        { 2928, "A", 20, 30, "沉默的舒尼", "暴风城 - 矮人区 63,34", nil, false, nil, {9608, 9609, 270045}, "收集 24 副机械内胆，交给暴风城的舒尼。", "所有机器人都掉内胆。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9309}, nil, 6579, "沉默的舒尼", { xp = 2450, rep = { {72, 100, "暴风城"}, {54, 100, "诺莫瑞根流亡者"} } } },
        { 2962, "A", 20, 30, "奥齐·电环", "丹莫罗 - 卡拉诺斯 45,49", "诺恩", false, {2926}, nil, "到诺莫瑞根收集高强度辐射尘（极不稳定、会很快分解），并把沉重的铅瓶一并交还奥齐。", "取样方法：对活着的辐射泥浆怪、辐射潜伏者、辐射水元素使用沉重的铅瓶。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9365, 9364}, nil, 1268, "奥齐·电环", { xp = 2450, money = 2500 } },
        { 2904, nil, 24, 30, "克努比", "诺莫瑞根", nil, true, nil, {9535, 9536, 270042}, "把克努比护送到出口，然后回藏宝海湾向斯库提汇报。", "护送任务。斯库提(荆棘谷-藏宝海湾 27,77)。护送终点是副本正门（送到门口即可，不用穿出去）；小侏儒不会主动引怪，潜行职业全程潜行也能做。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 7850, "克努比", { xp = 2450 } },
        { 2924, "A", 24, 30, "科劳莫特·钢尺", "铁炉堡 - 侏儒区 68,46", "帮助科劳莫特", false, {2925}, nil, "收集 12 个基础模组，交给铁炉堡的科劳莫特·钢尺。", "前置可从玛希尔接(达纳苏斯-战士区 59,45)。诺莫瑞根的所有敌人都可能掉。", {{24,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9278}, nil, 6169, "科罗莫特·钢尺", { xp = 3050, money = 5500, rep = { {54, 150, "诺莫瑞根流亡者"} } } },
        { 2841, "H", 25, 35, "诺格", "奥格瑞玛 - 荣誉谷 75,25", nil, false, nil, {9623, 9624, 9625}, "从诺莫瑞根取回钻探设备蓝图和麦克尼尔的保险箱密码，交给奥格瑞玛的诺格。", "麦克尼尔·瑟玛普拉格是诺莫瑞根最终 首领。战斗中记得按他旁边的按钮，阻止他丢炸弹。", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, {9153, 9299}, nil, 3412, "诺格", { xp = 2750, rep = { {76, 100, "奥格瑞玛"} } } },
        { 2929, "A", 25, 35, "大工匠梅卡托克", "铁炉堡 - 侏儒区 68,48", nil, false, nil, {9623, 9624, 9625}, "进入诺莫瑞根击杀麦克尼尔·瑟玛普拉格，完成后向大工匠梅卡托克报告。", "他是最终 首领。战斗中要按他旁边的按钮阻止他丢炸弹。", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7937, "大工匠梅卡托克", { xp = 2750, money = 3500, rep = { {54, 100, "诺莫瑞根流亡者"} } } },
