        { 1144, nil, 23, 30, "进口商威利克斯", "剃刀沼泽", nil, true, nil, {6748, 6750, 6749}, "护送进口商威利克斯逃出剃刀沼泽。", "护送时离他太远或太近都会判失败。进本右手穿过野猪区即到威利克斯，无需清任何首领。", {{22,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 4508, "进口商威利克斯", { xp = 3050, rep = { {470, 150, "棘齿城"} } } },
