        { 1109, "H", 30, 33, "法拉尼尔", "幽暗城 - 炼金房 48,69", nil, false, nil, nil, "替幽暗城的大药剂师法拉尼尔收集一份沼泽蝙蝠的粪便。", "只有副本最西侧、尾王卡尔加·刺肋前一厅的穴居蝙蝠会掉（掉率很高），要穿过大半个副本才能遇到它们。", {{30,2}, {31,3}, {36,4}, {42,5}}, {5801}, nil, 2055, "大药剂师法拉尼尔", { xp = 3300, rep = { {68, 150, "幽暗城"} } } },
