        { 3525, nil, 32, 37, "奔尼斯特拉兹", "剃刀高地", "剃刀高地的亡灵天灾", true, {3523}, {10710}, "陪奔尼斯特拉兹到剃刀高地的野猪人神像处，在他仪式封印神像时保护他。", "接受协助后仪式期间会不断刷怪攻击他，保证他不倒；完成后在神像前交付领奖。", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, nil, nil, 8516, "奔尼斯特拉兹", { xp = 4250 } },
