        { 7504, nil, 54, 60, "光明不会告诉你的事情", "厄运之槌的所有几个副本的 首领 都可能掉落", nil, false, nil, {18469}, "把这本典籍交给它的主人。", "牧师职业饰品任务。交给博学者亚沃（厄运之槌西 - 图书馆）。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18362}, "牧师", nil, nil, { xp = 6600, rep = { {809, 200, "辛德拉"} } } },
