        { 5282, nil, 55, 60, "埃根", "东瘟疫之地 11,29", "永不安息的灵魂", false, {5281}, {13315}, "对斯坦索姆的鬼魂居民使用埃根的冲击器；灵魂脱离躯壳后再用一次，让它们彻底安息。解放 15 个永不安息的灵魂后回埃根处复命。", "前置从护理者奥林处接(东瘟疫之地-圣光之愿礼拜堂 74,58)。鬼魂居民在城中到处游荡。冲击枪打中鬼魂约 10 秒后其身边会出现「不安的灵魂」，对它再补一枪即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "埃根", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, 60, "纳萨诺斯·凋零者", "东瘟疫之地 22,68", "暗翼蝠", false, {6135}, {18022, 17001}, "到斯坦索姆击杀吞咽者拉姆斯登，把头颅交给纳萨诺斯。", "前置同样在纳萨诺斯处接。拉姆斯登在副本内。", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "纳萨诺斯·凋零者", { xp = 6600, money = 18000, rep = { {68, 100, "幽暗城"} } } },
        { 5463, nil, 57, 60, "莱尼德·巴萨罗梅", "东瘟疫之地 - 圣光之愿礼拜堂 75,52", "亡灵莱斯·霜语", false, {5462}, nil, "到斯坦索姆找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。", "前置从马杜克镇长处接(西瘟疫之地-凯尔达隆 70,73)。标记就是男爵房间地上的五芒星。另见通灵学院的「巫妖莱斯·霜语」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "莱尼德·巴萨罗梅", { xp = 6600 } },
        { 8945, nil, 58, 60, "伊思达·哈尔蒙", "东瘟疫之地 - 斯坦索姆", "寻找安泰恩", false, {8929}, {22137}, "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。", "伊思达·哈尔蒙就站在副本门口，需要超维度幽灵显形器才能看到他。前置：联盟找德莉亚娜(铁炉堡 43,52)，部落找莫克瓦尔(奥格瑞玛 38,37)。这也是著名的「45 分钟瑞文戴尔」任务。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "安泰恩·哈尔蒙", { xp = 8300 } },
        { 8968, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "重要的材料", false, {8964}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克饰品左瓣还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8991, nil, 58, 60, "伯德雷", "黑石山 副本入口地图中的[D]", "更多重要的材料", false, {8987}, nil, "用召唤火盆召出亚雷恩和索托斯的灵魂并杀掉他们，把火盆和瓦塔拉克公爵的饰品还给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。两人在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7622, nil, 60, nil, "艾瑞斯·哈文法", "东瘟疫之地 17,14", "警示", false, {7621}, nil, "在 15 个农夫被杀之前拯救 50 个农夫，完成后与艾瑞斯·哈文法谈谈。拯救进度可以看死亡布告。", "见到艾瑞斯·哈文法并接任务需要神圣之眼（火焰之王的宝箱，熔火之心出）。完成后把神圣之眼、诺达希尔碎片和暗影之眼（诅咒之地/冬泉谷随机恶魔掉落）组合，得到牧师史诗法杖——祈福。", {{60,3}, {63,4}, {72,5}}, nil, "牧师", 14494, "艾瑞斯·哈文法", nil },
        { 9257, nil, 60, nil, "阿纳克洛斯", "塔纳利斯 - 时光之穴 65,49", "埃提耶什，被玷污的传说之杖", false, {9251}, nil, "塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什、守护者的传说之杖，击败被驱赶出来的生物后回他那里复命。", "召唤位置在副本内。巫妖王之怒资料片中无法再获得此任务；只有「召唤出埃提耶什」这一步仍可完成。", {{60,3}, {63,4}, {72,5}}, {22737}, "牧师", nil, nil, nil },
    },
    ["upper_blackrock_spire"] = {
        { 4788, nil, 40, 58, "勘查员詹斯·铁靴", "塔纳利斯 - 热砂港 66,23", "失落的摩沙鲁石板", false, {5065}, nil, "把第五、第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。", "第 5 块石板在暗影猎手沃什加斯的房间，第 6 块在战争大师沃恩的房间。奖励来自《面对叶基亚》；叶基亚就在詹斯·铁靴旁边。", {{40,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {12740, 12741}, nil, 10460, "勘查员詹斯·铁靴", { xp = 7750 } },
        { 8181, nil, 40, 58, "勘查员詹斯·铁靴", "塔纳利斯 - 热砂港 66.9,24", "失落的摩沙鲁石板", false, {4788}, {20218, 20219}, "去塔纳利斯找叶基亚，当面质问哈卡之蛋的下落。", "哈卡链收尾一环：热砂港的詹斯·铁靴(66.9,24)接，交任务在旁边的叶基亚(67,22.4)。链：尖啸者的灵魂→摩沙鲁的预言→…→失落的摩沙鲁石板→本任务；后续为《拉斯塔哈之手》。", {{40,1}, {54,2}, {56,3}}, nil, nil, 10460, "勘查员詹斯·铁靴", { xp = 6200 } },
        { 6502, "A", 50, 60, "哈尔琳", "冬泉谷", "巨龙之眼", false, {6501}, {16309}, nil, nil, {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10929, "哈尔琳", { xp = 8300 } },
        { 4729, nil, 55, 59, "基布雷尔", "燃烧平原 - 烈焰峰 65,22", nil, false, nil, {12264}, "到黑石塔捕捉血斧座狼幼崽：用笼子收服这些小家伙，把笼中的幼崽交给基布雷尔。", "座狼幼崽在副本内。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12263, 12262}, nil, 10260, "基布雷尔", { xp = 6400, money = 9000 } },
        { 4862, nil, 55, 59, "基布雷尔", "燃烧平原 - 烈焰峰 65,22", nil, false, nil, {12529}, "到黑石塔替基布雷尔收集 15 枚尖塔蜘蛛卵。", "蜘蛛卵在副本内。拾卵时会随机刷出小蜘蛛，伤害高还带 AOE，留意。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12530}, nil, 10260, "基布雷尔", { xp = 6400, money = 9000 } },
        { 4866, nil, 55, 60, "狼狈不堪的约翰", "燃烧平原 - 烈焰峰 65,23", nil, false, nil, {15873}, "在黑石塔中心找到烟网蛛后，与她战斗让她向你体内注入毒汁；有能力就顺手杀了她。中毒后回狼狈不堪的约翰那里，让他把「蛛后的乳汁」抽出来。", "烟网蛛后在副本内。注意：中途解毒会导致任务失败。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9563, "狼狈不堪的约翰", { xp = 9950, money = 18000 } },
        { 4974, "H", 55, 60, "萨尔", "奥格瑞玛 31,38", "伊崔格的智慧", false, {4941}, {13966, 13968, 13965}, "到黑石塔击杀大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。", "雷德·黑手在副本内。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12630}, nil, 4949, "萨尔", { xp = 9950, money = 27000, rep = { {76, 200, "奥格瑞玛"}, {530, 200, "暗矛巨魔"}, {68, 200, "幽暗城"}, {81, 200, "雷霆崖"} } } },
        { 4982, "H", 55, 59, "比修", "下层黑石塔", "狡猾的比修", true, {4981}, nil, "找回比修的装置还给她——她记得藏在城市最底层。", "装置在通往烟网蛛后的路上。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 4983, "H", 55, 59, "比修", nil, nil, true, {4982}, {15858, 15859}, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12652}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {76, 100, "奥格瑞玛"} } } },
        { 5001, "A", 55, 59, "比修", "下层黑石塔", nil, true, nil, nil, "找回比修的装置还给她。祝你好运！", "装置在通往烟网蛛后的路上。后续找麦克斯韦元帅(燃烧平原-摩根的岗哨 84,58)。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 5002, "A", 55, 59, "比修", nil, nil, true, {5001}, nil, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12770}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {72, 100, "暴风城"} } } },
        { 5047, nil, 55, 60, "芬克·恩霍尔", "上层黑石塔", nil, true, nil, nil, "与永望镇的玛雷弗斯·暗锤谈一谈。", "剥完比斯巨兽的皮后芬克·恩霍尔才会出现。玛雷弗斯·暗锤(冬泉谷-永望镇 61,38)。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "皮普·急智", { xp = 6600 } },
        { 5102, "A", 55, 60, "麦克斯韦尔元帅", "燃烧平原 - 摩根的岗哨 82,68", "达基萨斯将军的命令", false, {5089}, {13966, 13968, 13965}, "到黑石塔击杀达基萨斯将军，回麦克斯韦尔元帅处复命。", "达基萨斯将军在副本内。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "麦克斯韦尔元帅", { xp = 9950, money = 27000, rep = { {469, 200, "联盟"} } } },
        { 5127, nil, 55, 60, "罗拉克斯", "冬泉谷 64,74", "罗拉克斯的故事", false, {5126}, {12696, 9224, 12849}, "到黑石塔找到古拉鲁克，杀死后用血污长矛刺入尸体吸干灵魂炼成穿魂长矛；再找一块未铸造的符文覆饰胸甲，把两样都交给冬泉谷的罗拉克斯。", "锻造任务。古拉鲁克在副本内。需要锻造 270 才能接。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "罗拉克斯", { xp = 8300 } },
        { 6569, "H", 55, nil, "巫女麦兰达", "西瘟疫之地 50,77", "幻术的欺诈", false, {6568}, nil, "到黑石塔收集 20 颗黑色龙人的眼球，回巫女麦兰达处复命。", "黑龙系的敌人都会掉眼球。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "巫女麦兰达", { xp = 6600 } },
        { 6602, "H", 55, 60, "罗卡鲁", "凄凉之地 - 葬影村 25,71", "晋升……", false, {6601}, {16309}, "到黑石塔击杀达基萨斯将军，把他的血交给罗卡鲁。", "奥妮克西亚前置的最后一步。达基萨斯将军在副本内。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10182, "雷克萨", { xp = 9950 } },
        { 6821, nil, 55, nil, "海达克西斯公爵", "艾萨拉 79,73", "被囚禁的水元素", false, nil, nil, "把艾博希尔之眼交给艾萨拉的海达克西斯公爵。", "艾博希尔在副本内。3.0.8 补丁后无法再开启这条任务线；已接到的不受影响，仍可完成。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {17322}, nil, 13278, "海达克西斯公爵", nil },
        { 7761, nil, 55, nil, nil, "黑手的命令掉落自（副本入口地图）裂盾军需官。", nil, false, nil, nil, "真是头蠢兽人——找到那枚烙印，拿到达基萨斯徽记，才能使用命令宝珠。", "黑翼之巢的进门任务。裂盾军需官在黑石塔副本门口右侧附近；宝珠在达基萨斯将军身后。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18987}, nil, nil, nil, nil },
        { 4734, nil, 57, 60, "丁奇·斯迪波尔", "燃烧平原 - 烈焰峰 65,24", "丁奇·斯迪波尔", false, {4907}, {12144}, "在孵化间对一颗龙蛋使用龙蛋冷冻器初号机。", "龙蛋在烈焰之父的房间。冻蛋后别去点蛋，直接用背包里的装置；打完达基萨斯将军后可以直接跳下龙蛋房单独补做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "丁奇·斯迪波尔", { xp = 8300, money = 18000, rep = { {169, 150, "热砂港"} } } },
        { 4735, nil, 57, 60, "丁奇·斯迪波尔", "燃烧平原 - 烈焰峰 65,24", "冷冻龙蛋", false, {4734}, nil, "把电动采集模块和 8 颗龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。", "龙蛋都在烈焰之父的房间里。冻住蛋后靠近使用背包里的装置即可（不用点蛋）；团里没人管的话，打完将军跳下龙蛋房可单独补做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "丁奇·斯迪波尔", { xp = 9950, money = 27000, rep = { {169, 200, "热砂港"} } } },
        { 4743, nil, 57, 60, "裂盾渗透者", nil, "晋升印章", true, {4742}, {12344}, nil, "在龙下方的水中使用未铸造的印章开启铸印事件。事件一次只出 1 枚可拾取的锻造印章，且龙有 3 小时冷却——一晚只能做一个人。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12324, 12339}, nil, 10299, "裂盾渗透者", { xp = 9950 } },
        { 4764, "A", 57, 60, "玛亚拉·布莱特文", "燃烧平原 - 摩根的岗哨 84,69", "玛亚拉·布莱特文", false, {4766}, nil, "把末日扣环交给燃烧平原的玛亚拉·布莱特文。", "前置可从雷明顿·瑞治维尔伯爵接(暴风城-暴风要塞 77,47)。扣环在烈焰之父房间的箱子里。箱子约 20 秒刷新一次，多人可轮流开。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "玛亚拉·布莱特文", { xp = 1650, rep = { {72, 25, "暴风城"} } } },
        { 4765, "A", 57, 60, "玛亚拉·布莱特文", "燃烧平原", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "玛亚拉·布莱特文", { xp = 6600, money = 27000, rep = { {72, 100, "暴风城"} } } },
        { 4768, "H", 57, 60, "薇薇安·拉格雷", "荒芜之地 - 卡加斯 2,47", "薇薇安·拉格雷和黑暗石板", false, {4769}, {15861, 15860}, "把黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。", "前置可从药剂师金格接(幽暗城-炼金房 50,68)。石板在上层黑石塔的龙蛋房（孵化场）。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12358}, nil, 9078, "暗法师薇薇安·拉格雷", { xp = 8300, money = 27000, rep = { {68, 150, "幽暗城"} } } },
        { 5160, nil, 57, 60, "奥比", "上层黑石塔", nil, true, nil, nil, "到冬泉谷找到哈尔琳，把奥比的鳞片交给她。", "奥比在竞技场旁的房间，蹲在一处凸台上。哈尔琳(冬泉谷 54,51)；从洞穴最里面的传送符文站上去就能到她身边。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "奥比", { xp = 6600 } },
        { 8966, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "重要的材料", false, {8962}, nil, "用召唤火盆召出莫尔·灰蹄的灵魂并杀掉他，把火盆和瓦塔拉克饰品左瓣带回黑石山交给伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。莫尔·灰蹄在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {21984, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8989, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "更多重要的材料", false, {8986}, nil, "在比斯巨兽的房间用召唤火盆召出瓦塔拉克公爵，杀死后对尸体使用瓦塔拉克的饰品，再把饰品还给瓦塔拉克公爵之魂。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。莫尔·灰蹄在副本内召唤。", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8994, nil, 58, nil, "伯德雷", "黑石山 副本入口地图[D]", "瓦塔拉克饰品的右瓣", false, {8989}, nil, "从黑石塔的兽人身上收集 40 副黑石护腕，连同 1 瓶超级能量合剂一起交给黑石山的伯德雷。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。护腕由黑石塔兽人掉落；超级能量合剂是炼金制品。", {{58,3}, {63,4}, {72,5}}, {22138, 13512, 22048}, nil, 16033, "伯德雷", nil },
        { 8995, nil, 58, 60, "伯德雷", "黑石山 副本入口地图[D]", "最后的准备", false, {8994}, nil, "在比斯巨兽的房间用召唤火盆召出瓦塔拉克公爵，杀死后对尸体使用瓦塔拉克的饰品，再把饰品还给瓦塔拉克公爵之魂。", "需要超维度幽灵显形器才能看到伯德雷（从《寻找安泰恩》获得）。瓦塔拉克公爵在副本内召唤；奖励向伯德雷领取。", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "伯德雷", { xp = 9950 } },
    },
    ["onyxias_lair"] = {
        { 4182, "A", 48, 54, "赫林迪斯·河角", "燃烧平原 - 摩根的岗哨 85.6,69", nil, false, nil, nil, "猎杀燃烧平原的黑龙人，向赫林迪斯·河角复命。", "联盟开门链第一步。黑龙蛋、黑龙幼崽是非精英，黑龙人、黑翼龙人是 50-54 精英，建议组队；都集中在地图东部边缘一线。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9562, "赫林迪斯·河角", nil },
        { 4183, "A", 48, 54, "赫林迪斯·河角", "燃烧平原 - 摩根的岗哨 85.6,69", nil, false, {4182}, nil, "把赫林迪斯·河角的信送到赤脊山湖畔镇的所罗门镇长手中。", "同名任务共五段，从湖畔镇一路辗转推进到暴风城。本段终点：湖畔镇市政厅(赤脊山 30,44)。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 344, "所罗门镇长", nil },
        { 4241, "A", 50, 58, "麦克斯韦尔元帅", "燃烧平原 - 摩根的岗哨 84.6,68.8", nil, false, {4183}, nil, "到黑石深渊监狱探视被囚的温德索尔元帅，把麦克斯韦尔元帅的信交给他。", "温德索尔在深渊监狱区右侧走廊尽头的牢房里。◎ 注意区分：麦克斯韦尔元帅在燃烧平原的摩根的岗哨，温德索尔元帅在深渊牢里。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "温德索尔元帅", nil },
        { 6402, "A", 50, 60, "麦克斯韦尔元帅", "燃烧平原 - 摩根的岗哨 84.6,68.8", nil, false, {4322}, nil, "到暴风城门口找侍从罗威，召出雷吉纳德·温德索尔，护送他从城门走到暴风要塞。", "护送全程约 10 分钟；若别的队伍正在护送，温德索尔会说他暂时脱不开身，等几分钟就会现身。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 12580, "雷吉纳德·温德索尔", nil },
        { 6403, "A", 50, 60, "雷吉纳德·温德索尔", "暴风城 - 城门 70.4,85.6", nil, false, {6402}, nil, "陪雷吉纳德·温德索尔行进到暴风要塞，击杀卡特拉娜·普瑞斯托现形后召出的精英龙人卫兵，向伯瓦尔·弗塔根公爵复命。", "假面游行：普瑞斯托女男爵现出奥妮克希亚原形并召唤精英龙人卫兵，场边的卫兵 NPC 会帮忙抗怪，全清后交任务。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 1748, "伯瓦尔·弗塔根公爵", nil },
        { 6501, "A", 50, 60, "伯瓦尔·弗塔根公爵", "暴风城", nil, false, {6403}, nil, "带着龙眼碎片到冬泉谷南部的马兹索里尔洞穴深处，找伪装成人类的巨龙哈尔琳。", "哈尔琳在洞穴尽头的传送符文处，踩上符文就会传到她身边。洞里精英龙人很多：组队清过去、盗贼潜行、或开疾跑直接冲，都能到她跟前。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 10929, "哈尔琳", nil },
        { 4941, "H", 55, 60, "高图斯", "荒芜之地 - 卡加斯 5.8,47.6", nil, false, {4903}, nil, "到奥格瑞玛智慧谷找伊崔格谈话，再把他的话带给萨尔。", "伊崔格在智慧谷(34.4,38.4)，谈完直接回萨尔(奥格瑞玛 31,38)交任务。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "萨尔", nil },
        { 6566, "H", 55, 60, "萨尔", "奥格瑞玛 31,38", nil, false, {4974}, nil, "听萨尔讲完黑龙的故事，向他复命。", "纯对话任务，站着听完就行。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "萨尔", nil },
        { 6567, "H", 55, 60, "萨尔", "奥格瑞玛 31,38", nil, false, {6566}, nil, "到凄凉之地寻找部落的勇士雷克萨。", "雷克萨沿石爪山脉至菲拉斯的大道来回巡逻，中途会穿过科多兽墓地；找不到就问凄凉之地综合频道，或从菲拉斯沿路往北走最容易堵到他。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "雷克萨", nil },
        { 6568, "H", 55, 60, "雷克萨", "凄凉之地 - 通往菲拉斯的大道", nil, false, {6567}, nil, "把雷克萨的嘱托送到西瘟疫之地乌瑟尔之墓附近的巫女麦兰达手中。", "麦兰达(西瘟疫之地 50,77)，她会教你伪装成黑龙军团成员的办法。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11872, "巫女麦兰达", nil },
        { 6570, "H", 55, 60, "巫女麦兰达", "西瘟疫之地 50,77", nil, false, {6569}, nil, "戴上龙族伪装护符，到尘泥沼泽最南端的洞穴里与埃博斯塔夫对话。", "进洞走到最深处先使用「龙族伪装护符」，再与埃博斯塔夫说话。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6582, "H", 55, 60, "埃博斯塔夫", "尘泥沼泽 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "击杀冬泉谷马兹索里尔洞穴里的蓝龙斯克莱尔，取回头骨交给埃博斯塔夫。", "《颅骨试炼》三场顺序随意、可以团杀；斯克莱尔(马兹索里尔洞穴深处 53.2,56)，洞口(冬泉谷-马兹索里尔洞穴 57,50)，要清不少精英龙人。◎ 三条龙都别忘摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6583, "H", 55, 60, "埃博斯塔夫", "尘泥沼泽 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "击杀悲伤沼泽的绿龙索姆努斯，取回头骨交给埃博斯塔夫。", "索姆努斯在地图东南部大范围巡逻(约 80,70 附近)，先清一片区域等他路过。他有很强的击退，自然抗性很吃香。三场试炼顺序随意，记得摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6584, "H", 55, 60, "埃博斯塔夫", "尘泥沼泽 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "击杀塔纳利斯时光洞穴外的青铜龙克罗纳利斯，取回头骨交给埃博斯塔夫。", "克罗纳利斯在时光洞穴门口(64.6,50.2)。三场试炼顺序随意、可以团杀，记得摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6585, "H", 55, 60, "埃博斯塔夫", "尘泥沼泽 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6582, 6583, 6584}, nil, "击杀湿地的红龙阿克特罗兹，取回头骨交给埃博斯塔夫。", "前三场颅骨试炼交完才会开放。阿克特罗兹在格瑞姆巴托附近巡逻(约 85,49)，火焰免疫；想剥皮需要剥皮技能 310。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6601, "H", 55, 60, "埃博斯塔夫", "尘泥沼泽 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6585}, nil, "带着暗淡的龙火护符去凄凉之地找雷克萨。", "任务描述让你回黑石塔找达基萨斯将军，但伪装护符在黑石塔里不生效——直接去凄凉之地找雷克萨（巡逻路线同《部落的勇士》）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "雷克萨", nil },
    },
}

