    [92432] = { lv = 33, lvStd = 30, nm = "紧急求援", npc = "使者雅克", npcid = 247264, side = "A", zone = "希尔斯布莱德丘陵", gains = { xp = 660 }, obj = "向达拉然城附近的大法师莫德拉的影像汇报。", text = "在希尔斯布莱德丘陵南海镇的使者雅克处接取，汇报给达拉然城副本外的大法师莫德拉的影像。" },
    [92434] = { lv = 34, lvStd = 30, nm = "喋血街头", npc = "大法师沃迪恩·伍德格莱尔", npcid = 2410, side = "H", zone = "希尔斯布莱德丘陵", goals = { { "i", 279469, 1 } }, gains = { xp = 270 }, obj = "沿洛丹伦湖寻找进入达拉然城的办法。", text = "在塔伦米尔的大法师沃迪恩·伍德格莱尔处接取，沿洛丹伦湖岸找到达拉然下水道入口潜入城中，交付给城外的大法师莫德拉的影像。" },
    [92742] = { lv = 9, lvStd = 12, nm = "测试水井", npc = "阿尔巴·晴月", npcid = 253092, zone = "西部荒野", goals = { { "i", 254546, 1 }, { "i", 254547, 1 }, { "i", 254545, 1 } }, gains = { xp = 455, money = 250, rep = { { 72, 50, "暴风城" } } }, obj = "使用井水采样工具包，从詹森农场和莫尔森农场的水井中采集样本。", text = "在西部荒野找阿尔巴·晴月接；带井水采样工具包到詹森农场和莫尔森农场的水井取样，两处都要采。" },
    [92744] = { lv = 9, lvStd = 12, nm = "鱼人的鳃", npc = "阿尔巴·晴月", npcid = 253092, zone = "西部荒野", goals = { { "i", 254548, 7 } }, gains = { xp = 455, money = 250, rep = { { 72, 50, "暴风城" } } }, obj = "阿尔巴·晴月要你在西部荒野海岸沿线收集7份长岸鱼人鳃。", text = "沿西部荒野海岸线猎杀长岸鱼人，凑齐 7 份鱼人鳃交给阿尔巴·晴月。" },
    [92745] = { lv = 9, lvStd = 14, nm = "矿洞近况", npc = "阿尔巴·晴月", npcid = 253092, zone = "西部荒野", goals = { { "c", "狗头人掘地工", 4 }, { "c", "河爪矿工", 6 } }, gains = { xp = 490, money = 300, rep = { { 72, 50, "暴风城" } } }, obj = "在詹戈洛德矿洞消灭4名狗头人掘地工，并在金海岸矿洞消灭6名河爪矿工。", text = "进詹戈洛德矿洞杀 4 名狗头人掘地工，再去金海岸矿洞杀 6 名河爪矿工，打完回阿尔巴处。" },
